"""Serve the generated public API reference (#655)."""

from pathlib import Path

from flask import Blueprint, send_from_directory

bp = Blueprint("api_docs", __name__, url_prefix="/api")

DOCS_DIR = Path(__file__).resolve().parents[2] / "docs" / "api"


@bp.route("/docs")
@bp.route("/docs/")
def api_docs():
    """Return the static reference generated by ``scripts/render_api_docs.py``."""
    return send_from_directory(DOCS_DIR, "index.html")
